package com.kenznguyen.btclivealerts

import org.json.JSONArray
import org.json.JSONObject
import java.security.MessageDigest

/** Deterministic offline trace generated by the actual Kotlin engine. No orders or state writes. */
internal data class KotlinReplayTrace(
    val state: StrategyState, val events: List<StrategyEvent>, val json: JSONObject
)
internal object StrategyTraceExporter {
    private fun canonical(candles: List<Candle>, label: String): String =
        candles.filter { it.closed }.sortedBy { it.openTime }.joinToString("\n") { c ->
            listOf(label, c.openTime.toString(), c.open.toString(), c.high.toString(),
                c.low.toString(), c.close.toString(), c.volume.toString()).joinToString(",")
        }

    fun datasetHash(m15: List<Candle>, h1: List<Candle>): String {
        val payload = canonical(m15, "15m") + "\n" + canonical(h1, "1h")
        val digest = MessageDigest.getInstance("SHA-256")
            .digest(payload.toByteArray(Charsets.UTF_8))
        return "sha256:" + digest.joinToString("") { "%02x".format(it.toInt() and 0xff) }
    }

    fun replay(engine: StrategyEngine, m15: List<Candle>, h1: List<Candle>,
               original: StrategyState): KotlinReplayTrace {
        val (state, events) = engine.processClosedCandles(m15, h1, original)
        val hash = datasetHash(m15, h1)
        val rows = JSONArray()
        events.forEach { ev ->
            rows.put(JSONObject()
                .put("id", (ev.side ?: "FLAT") + ":" + ev.candleTime)
                .put("kind", ev.kind)
                .put("candleTime", ev.candleTime)
                .put("side", ev.side ?: JSONObject.NULL)
                .put("price", ev.price)
                .put("confirmed_at_ms", if (ev.kind == "EMERGENCY SL") ev.candleTime else ev.candleTime + 900_000L)
                .put("fees", ev.fees ?: JSONObject.NULL)
                .put("net_pnl", ev.netPnl ?: JSONObject.NULL))
        }
        return KotlinReplayTrace(state, events, JSONObject()
            .put("engine", "kotlin")
            .put("dataset_sha256", hash)
            .put("events", rows)
            .put("source", "StrategyEngine.processClosedCandles")
            .put("parity_verified", false))
    }
}
